// Agrupa los clusters pendientes en lotes de 20. A diferencia de 05 (1 cluster
// por llamada, prompt de miles de tokens con el texto completo de cada
// artículo), aquí el input por cluster son ~60 tokens: el 'que_paso' que 05 ya
// dejó escrito más los titulares. Caben muchos clusters en una sola llamada.
//
// El tamaño de lote no lo limita el contexto del modelo sino su techo de
// 6.000 tokens/minuto: 20 clusters son ~3.000 tokens, media ventana de un
// minuto. De ahí el batchInterval de 40s del nodo HTTP (ver docs/07).
const BATCH_SIZE = 20;
const clusters = $input.all().map(item => item.json);

const batches = [];
for (let i = 0; i < clusters.length; i += BATCH_SIZE) {
  batches.push(clusters.slice(i, i + BATCH_SIZE));
}

return batches.map(batch => ({ json: { clusters: batch } }));

const MAX_TITLES_CHARS = 300;

const RULES = `Eres un editor de noticias. Vas a asignar una categoría temática a una lista de acontecimientos. Cada acontecimiento viene descrito por lo que pasó y por los titulares con los que distintos medios lo cubrieron.

Asigna a cada acontecimiento exactamente UNA categoría de esta lista cerrada, según su alcance:
- internacional: hechos ocurridos fuera de España o entre países (política exterior, conflictos, gobiernos extranjeros, catástrofes en el extranjero).
- economia: mercados, bolsa, empresas, fusiones, empleo, precios, banca, moneda, política monetaria o fiscal, finanzas de particulares.
- tecnologia: informática, internet, inteligencia artificial, ciberseguridad, telecomunicaciones, electrónica de consumo.
- ciencia: investigación científica, medicina, espacio, hallazgos y estudios.
- espana: política, instituciones, justicia, administración y sucesos de ámbito español.
- cultura: arte, música, cine, series, literatura, espectáculo, celebridades y patrimonio.
- deportes: competición deportiva, sus protagonistas e instituciones.
- sociedad: SOLO si no encaja en ninguna de las anteriores (educación, salud pública, conflictos laborales, fenómenos sociales).

Criterios de desempate:
- Clasifica por la materia del hecho, no por el país donde ocurre ni por quién lo protagoniza.
- Si un hecho ocurre en España pero su materia principal es económica, tecnológica, científica, cultural o deportiva, prevalece esa materia sobre "espana".
- Del mismo modo, si un hecho ocurre fuera de España pero su materia principal es económica, tecnológica, científica, cultural o deportiva, prevalece esa materia sobre "internacional". Reserva "internacional" para política exterior, conflictos armados y gobiernos de otros países.
- No uses "sociedad" si alguna categoría concreta encaja.

No inventes categorías ni uses ninguna fuera de la lista. Responde ÚNICAMENTE con un JSON: un array "clusters" con un objeto por acontecimiento, en el mismo orden en que se dan, cada uno con "indice" (el número del acontecimiento) y "categoria".`;

const items = $input.all();

return items.map(item => {
  const batch = item.json.clusters;
  const blocks = batch.map((c, i) => {
    const titles = String(c.titles || '').slice(0, MAX_TITLES_CHARS);
    return `[${i}] Qué pasó: ${c.que_paso || '(sin resumen)'}\nTitulares: ${titles}`;
  });
  const prompt = `${RULES}\n\nAcontecimientos:\n\n${blocks.join('\n\n')}`;

  return {
    json: {
      clusters: batch,
      prompt
    }
  };
});

const VALID = ['internacional', 'economia', 'tecnologia', 'ciencia', 'espana', 'cultura', 'deportes', 'sociedad'];

function stripTrailingCommas(text) {
  return text.replace(/,(\s*[}\]])/g, '$1');
}

function extractJson(raw) {
  const withoutThink = raw.replace(/<think>[\s\S]*?<\/think>/i, '').trim();
  const cleaned = stripTrailingCommas(withoutThink);
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const start = cleaned.indexOf('{');
    const end = cleaned.lastIndexOf('}');
    if (start === -1 || end === -1 || end <= start) {
      throw new Error(`No se encontró un JSON válido en la respuesta del LLM. Respuesta cruda (primeros 500 caracteres): ${raw.slice(0, 500)}`);
    }
    const candidate = cleaned.slice(start, end + 1);
    try {
      return JSON.parse(candidate);
    } catch (e2) {
      throw new Error(`JSON extraído no parseable: ${e2.message}. Candidato (primeros 500 caracteres): ${candidate.slice(0, 500)}`);
    }
  }
}

// Normaliza acentos/mayúsculas antes de validar: el modelo devuelve a veces
// "España" o "Economía" pese a que el prompt pide la lista sin tildes.
function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

const items = $input.all();
const output = [];

items.forEach((item, idx) => {
  // itemMatching resuelve el lote de origen real vía pairedItem, no por posición
  // dentro de esta rama: n8n reindexa desde 0 cada rama de un split éxito/error.
  const batchClusters = $('Build Prompt per Batch').itemMatching(idx).json.clusters;

  let results;
  try {
    const raw = item.json.choices?.[0]?.message?.content;
    if (!raw) {
      throw new Error(`Respuesta de Groq sin contenido esperado. Payload recibido: ${JSON.stringify(item.json).slice(0, 500)}`);
    }
    const parsed = extractJson(raw);
    results = parsed.clusters || parsed;
    if (!Array.isArray(results)) {
      throw new Error(`Se esperaba un array "clusters" en la respuesta. JSON recibido: ${JSON.stringify(parsed).slice(0, 500)}`);
    }
  } catch (e) {
    // Lote entero no parseable: no se emite ninguna fila. Sus clusters se quedan
    // con categoria NULL, que es exactamente la cola de trabajo — reentran solos
    // en la próxima ejecución sin necesidad de columna de estado.
    console.log(`Lote ${idx} descartado: ${e.message}`);
    return;
  }

  batchClusters.forEach((cluster, i) => {
    const r = results.find(x => x.indice === i) || results[i];
    const categoria = normalize(r?.categoria);

    if (!VALID.includes(categoria)) {
      // Categoría ausente o fuera de la lista cerrada: se deja sin escribir en
      // vez de forzar un valor inventado. Sigue en cola para el próximo intento.
      console.log(`Cluster ${cluster.id} sin categoría válida (recibido: ${JSON.stringify(r?.categoria)})`);
      return;
    }

    output.push({
      json: {
        id: cluster.id,
        categoria,
        que_paso: cluster.que_paso,
        source_count: cluster.source_count
      }
    });
  });
});

return output;

// Rama de error de "Call Groq for Categorization" (onError: continueErrorOutput).
// No escribe nada en Postgres a propósito: los clusters del lote fallido se
// quedan con categoria NULL y vuelven a entrar en la cola en la siguiente
// ejecución. La ausencia de categoría ya es el registro de "pendiente", así que
// aquí solo se deja traza legible en el log de la ejecución.
const items = $input.all();

return items.map((item, idx) => {
  const batchClusters = $('Build Prompt per Batch').itemMatching(idx).json.clusters;
  const errorMessage =
    item.json?.error?.message ||
    item.json?.error ||
    item.json?.message ||
    `Fallo en la llamada a Groq sin mensaje de error legible: ${JSON.stringify(item.json).slice(0, 300)}`;

  return {
    json: {
      failed_cluster_ids: batchClusters.map(c => c.id),
      error_message: String(errorMessage).slice(0, 1000)
    }
  };
});

// El UPDATE de Postgres no devuelve las filas afectadas, así que sin este paso
// el valor de retorno del workflow sería la confirmación vacía de Postgres en
// vez de las categorías asignadas (mismo motivo que "Return New Articles" en
// 03-deduplication).
return $('Parse & Validate Categories').all();
